<script setup lang="ts">
import { onMounted, reactive, shallowRef } from 'vue'
import { ElMessage } from 'element-plus'
import * as api from '../../api/sla'
import { useAuthStore } from '../../stores/auth'
import { priorityLabel, priorityType } from '../../utils/workOrderStatus'
const auth=useAuthStore();const loading=shallowRef(false);const rules=shallowRef<any[]>([]);const events=shallowRef<any[]>([]);const total=shallowRef(0);const tab=shallowRef('rules')
const query=reactive<any>({eventType:null,handled:null,page:1,size:10});const editor=reactive<any>({visible:false,id:null,priority:null,responseMinutes:1,resolveMinutes:1,enabled:true})
async function load(){loading.value=true;try{const [r,e]=await Promise.all([api.rules(),api.events(query)]);rules.value=r.data;events.value=e.data.records;total.value=e.data.total}catch(error:any){ElMessage.error(error.response?.data?.message||'SLA数据加载失败')}finally{loading.value=false}}
function edit(row:any){Object.assign(editor,{visible:true,...row})}
async function save(){if(editor.responseMinutes>editor.resolveMinutes)return ElMessage.warning('响应时限不能超过解决时限');loading.value=true;try{await api.updateRule(editor.id,{responseMinutes:editor.responseMinutes,resolveMinutes:editor.resolveMinutes,enabled:editor.enabled});ElMessage.success('SLA规则已更新，仅影响后续新工单');editor.visible=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.message||'规则更新失败')}finally{loading.value=false}}
async function handle(row:any){try{await api.handleEvent(row.id);ElMessage.success('事件已标记处理');await load()}catch(e:any){ElMessage.error(e.response?.data?.message||'处理失败')}}
const eventLabel=(v:string)=>v==='RESPONSE_TIMEOUT'?'响应超时':'解决超时'
onMounted(load)
</script>
<template><section class="module-page"><header class="module-header"><div><p class="eyebrow">SERVICE LEVEL CONTROL</p><h1>SLA 管理</h1><p>配置新维修工单时限，跟踪响应与解决超时事件。</p></div></header><el-alert title="规则修改只影响修改后创建的维修工单；历史工单截止时间保持不变。" type="info" :closable="false"/><el-card shadow="never"><el-tabs v-model="tab"><el-tab-pane label="规则配置" name="rules"><el-table v-loading="loading" :data="rules"><el-table-column label="故障等级" width="150"><template #default="{row}"><el-tag :type="priorityType(row.priority)">{{priorityLabel(row.priority)}}</el-tag></template></el-table-column><el-table-column prop="responseMinutes" label="响应时限（分钟）"/><el-table-column prop="resolveMinutes" label="解决时限（分钟）"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" min-width="170"/><el-table-column v-if="auth.hasPermission('sla:rule:update')" label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="edit(row)">修改</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="超时事件" name="events"><el-form inline class="compact-filter"><el-form-item label="类型"><el-select v-model="query.eventType" clearable><el-option label="响应超时" value="RESPONSE_TIMEOUT"/><el-option label="解决超时" value="RESOLVE_TIMEOUT"/></el-select></el-form-item><el-form-item label="处理状态"><el-select v-model="query.handled" clearable><el-option label="待处理" :value="false"/><el-option label="已处理" :value="true"/></el-select></el-form-item><el-button type="primary" @click="query.page=1;load()">查询</el-button></el-form><el-table v-loading="loading" :data="events"><el-table-column prop="workOrderNo" label="工单编号" min-width="180"/><el-table-column label="等级" width="90"><template #default="{row}">{{priorityLabel(row.priority)}}</template></el-table-column><el-table-column label="事件" width="110"><template #default="{row}"><el-tag type="danger">{{eventLabel(row.eventType)}}</el-tag></template></el-table-column><el-table-column prop="deadline" label="截止时间" width="168"/><el-table-column prop="occurredAt" label="发生时间" width="168"/><el-table-column prop="escalatedToUserName" label="升级对象" min-width="110"><template #default="{row}">{{row.escalatedToUserName||'待人工处理'}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.handled?'success':'warning'">{{row.handled?'已处理':'待处理'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/work-orders/${row.workOrderId}`)">查看工单</el-button><el-button v-if="!row.handled&&auth.hasPermission('sla:event:handle')" link @click="handle(row)">标记处理</el-button></template></el-table-column></el-table><div class="pagination-row"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" layout="total,prev,pager,next" @change="load"/></div></el-tab-pane></el-tabs></el-card><el-dialog v-model="editor.visible" title="修改 SLA 规则" width="480px"><el-alert :title="`${priorityLabel(editor.priority)}故障`" description="保存后仅用于新建维修工单，不重新计算历史截止时间。" type="warning" :closable="false"/><el-form label-width="130px" class="dialog-form"><el-form-item label="响应时限（分钟）"><el-input-number v-model="editor.responseMinutes" :min="1" style="width:100%"/></el-form-item><el-form-item label="解决时限（分钟）"><el-input-number v-model="editor.resolveMinutes" :min="1" style="width:100%"/></el-form-item><el-form-item label="规则状态"><el-switch v-model="editor.enabled" active-text="启用" inactive-text="停用"/></el-form-item></el-form><template #footer><el-button @click="editor.visible=false">取消</el-button><el-button type="primary" :loading="loading" @click="save">保存规则</el-button></template></el-dialog></section></template>
